	(237, NULL, NULL, 0, 0, -1, NULL, 3060090000069, NULL, 1, 1, -1, 1, 0, 'Tiệm Pet Mỹ Mỹ', -1, -1, 0, 'Chào mừng đến với tiệm pet Xuất Vân Thôn, nơi đây có bán các loại thuốc tăng thọ mệnh và trung thành của pet, ngươi có cần ta giúp gì không?', 0, 1, 825, 371, NULL, -1, 2060090000069, -1, NULL, 45, NULL, '-1', 1, 2, 1),
	(239, NULL, 0, 0, 0, -1, NULL, 3060090000057, NULL, 1, 1, -1, 1, 0, 'Tiệm Tạp Hóa Ông Triệu', -1, -1, 0, 'Hàng hóa đều được bày trên giá, cần gì thì cứ chọn nhé.', 7, 1, 1504, 445, NULL, -1, 2060090000057, -1, NULL, 4, NULL, '-1', -1, 2, 1),
	(240, NULL, NULL, 0, 0, -1, NULL, 3060090000001, NULL, 1, 1, -1, 1, 0, 'Tân Thủ Sứ', -1, -1, 0, 'Học tập là một chặng đường tuy dài nhưng lại tràn ngập niềm vui… Mỗi một tân thủ khi đến đây đều mang theo ước mơ và hi vọng của mình, mong mỏi sẽ có ngày thành tài!', 0, 1, 275, 1052, NULL, -1, 2060090000001, -1, NULL, NULL, NULL, '-1', -1, 1, 1),
	(272, NULL, 0, 0, 0, -1, NULL, 3060090000015, NULL, 1, 1, -1, 1, 0, 'Tộc Trưởng Bối Tư', -1, -1, -1, 'Đông Huyền của chúng ta là do sáu tộc lớn chung sức dựng lên, cơ sở chính sẽ đóng ở thành Đông Huyền', 7, 9, 1699, 1462, NULL, -1, 2060090000015, -1, NULL, NULL, NULL, '-1', -1, 1, 1),
	(277, NULL, NULL, 0, 0, -1, NULL, 3060090000010, NULL, 1, 1, -1, 1, 0, 'Trưởng Cận Vệ Đông Huyền', -1, -1, 0, 'Bảo vệ thành Đông Huyền là trách nhiệm của chúng ta', 7, 9, 3181, 555, NULL, -1, 2060090000010, -1, NULL, 0, NULL, '-1', -1, 1, 1),
	(280, NULL, NULL, 0, 0, -1, NULL, 3060090000069, NULL, 1, 1, -1, 1, 0, 'Tiệm Pet Tôn Lệ', -1, -1, 0, 'Xin chào, hoan nghênh đến với tiệm Pet Đông Huyền, ta là Tôn Lệ, sẵn lòng phục vụ quý khách. Tiệm ta chuyên bán các vật phẩm liên quan đến Pet, cung cấp các vật tư trên lộ trình của ngươi và thú cưng. Tất nhiên, nuôi dưỡng và trang bị cho Pet là một nghệ', 0, 9, 1402, 699, NULL, -1, 2060090000069, -1, NULL, 43, NULL, '-1', -1, 2, 1),
	(287, NULL, 0, 0, 0, -1, NULL, 3060090000010, NULL, 1, 1, -1, 1, 0, 'Cận Vệ Đông Huyền', -1, -1, -1, 'Xin chào, ta là cận vệ ở Đông Huyền Thành, được phân công canh gác nơi đây.', 0, 6, 2154, 464, NULL, -1, 2060090000010, -1, NULL, 0, NULL, '2513', 1, 10, 1),
	(291, NULL, NULL, 0, 0, -1, NULL, 3060090000002, NULL, 1, 1, -1, 1, 0, 'Tiệm Vũ Khí Madoff', -1, -1, 0, 'Hoan nghênh đã đến tiệm vũ khí Madoff thành Tinh Linh, ta là thợ rèn Madoff. Tuy tay nghề của ta không thể so sánh được với anh ta là Mark, nhưng sử dụng nguyên liệu từ Khoáng Thạch đặc sản của thành Tinh Linh được tinh luyện và dát mỏng thì cũng không kh', 0, 10, 2066, 1677, NULL, -1, 2060090000002, -1, NULL, 51, NULL, '-1', -1, 2, 1),
	(295, NULL, NULL, 0, 0, -1, NULL, 3060090000010, NULL, 1, 1, -1, 1, 0, 'Vệ Sĩ Tinh Linh', -1, -1, 0, 'Này! Người ta cần là ngươi đó. Có hứng thú gia nhập đội của ta không?', 0, 10, 903, 837, NULL, -1, 2060090000010, -1, NULL, NULL, NULL, '-1', -1, 1, 1),
	(300, NULL, NULL, 0, 0, -1, '|15,Lê Dương Bắc,1000,1763,637|', 3060100000037, NULL, 1, 1, -1, 1, 0, 'Mật Đạo Tiểu Binh', -1, -1, 0, 'Ngươi muốn về Lê Dương Bắc ư?', 7, 140106, 1346, 716, NULL, -1, 2060090100037, -1, NULL, NULL, NULL, '-1', -1, 9, 1),
	(304, NULL, NULL, 0, 0, -1, NULL, 3060090000001, NULL, 1, 1, -1, 1, 0, 'Tiệm Trang Sức Khả Vi Nhi', -1, -1, 0, 'Đồng bằng này đầy rẫy những viên Bảo Thạch kì lạ, dùng những viên đá này để làm trang sức thì không chỉ đẹp lấp lánh mà còn có hiệu quả thần kỳ khác nhau.', 0, 9, 1959, 2304, NULL, -1, 2060090000001, -1, NULL, 27, NULL, '-1', -1, 2, 1),
	(307, NULL, NULL, 0, 0, -1, NULL, 3060090000004, NULL, 1, 1, -1, 1, 0, 'Tiệm Trang Sức Văn Văn', -1, -1, 0, 'Hoan nghênh đến với tiệm trang sức thành Tinh Linh.', 0, 10, 1920, 1869, NULL, -1, 2060090000004, -1, NULL, 28, NULL, '-1', -1, 2, 1),
	(312, NULL, NULL, 2, 0, -1, NULL, 3060090000012, NULL, 1, 1, -1, 1, 0, 'Đạo Sư Liêu Vân', -1, -1, 0, 'Hoan nghênh đến với thánh địa của đồ ăn ngon và linh hồn của nghệ thuật âm nhạc - Liêu Vân Tộc. Liêu Vân Tộc là nơi hội tụ của nhưng người có tâm hồn và khát khao nghệ thuật, vẻ cổ kính của nó gắn liền với thời âm nhạc mới xuất hiện tại đại lục Vô Ưu, điề', 0, 13, 570, 571, NULL, -1, 2060090000012, -1, NULL, NULL, NULL, '3-0', -1, 11, 1),
	(325, NULL, 0, 0, 0, -1, NULL, 3050070000002, NULL, 1, 1, -1, 1, 0, 'Kho Sách Linh Vũ', -1, -1, 0, 'Nơi đây có bán sách kỹ năng.', 0, 11, 781, 309, NULL, -1, 2060090300008, -1, NULL, 22, NULL, '-1', -1, 2, 1),
