	(182, NULL, 0, 0, 0, 2, NULL, 3060100001059, NULL, 1, -1, -2, -1, 0, 'Chiến Thần', 1, -1, -1, NULL, 0, 200, 1500, 1500, NULL, 1, 2060090100059, -1, NULL, NULL, NULL, 'all', 1, 10, 1),
	(191, NULL, NULL, 0, 0, -1, NULL, 3050070000006, NULL, 1, 1, -1, 1, 0, 'Thủ Hoang Nhân Tầng 2', -1, -1, -1, 'Cần phải cẩn thận với những nguy hiểm phía trước.', 0, 501, 948, 3473, NULL, -1, 2060090200034, -1, NULL, NULL, NULL, '-1', -1, 1, 1),
	(192, NULL, 0, 0, 0, -1, NULL, 3060100001100, NULL, 1, 1, -1, 1, 0, 'Người Thần Bí', -1, -1, -1, 'Tầng thứ ba là một ma pháp trận, tương truyền là do Tư tế Ai Cập cổ thiết lập để ngăn chặn người ngoài xâm nhập. Tuy nhiên nó cũng có quy luật nhất định: Giữa các ma pháp trận tương đồng nhau sẽ có thể dịch chuyển qua lại…', 0, 502, 600, 4100, NULL, 1, 2060090100100, -1, NULL, NULL, NULL, '-1', -1, 1, 1),
	(198, NULL, 0, 0, 0, -1, NULL, 3060090000061, NULL, 1, 1, -1, 1, 0, 'Sứ Giả Dịch Chuyển Đại Mạc', -1, -1, -1, NULL, 0, 14, 270, 758, NULL, -1, 2060090000061, -1, NULL, 0, NULL, '-1', 1, 1, 1),
	(202, NULL, 0, 0, 180, -1, NULL, 3060090000071, '5-3', 1, 1, -1, -1, 0, 'Bảo Rương Cổ', -1, -1, 1, 'Rương khá cũ, có vẻ chứa đựng một báu vật thần bí nào đó', 0, 503, 2384, 1512, '|1462', -1, 2060090000071, 3, NULL, 0, NULL, '2', -1, 24, 1),
	(211, NULL, 0, 0, 0, -1, NULL, 3060090000010, NULL, 1, 1, -1, 1, 0, 'Quản Lý Bang Hội Chiến', -1, -1, -1, NULL, 0, 9, 1569, 421, NULL, -1, 2060090000010, -1, NULL, NULL, NULL, '-1', 1, 1, 1),
	(425, NULL, 0, 0, 0, -1, NULL, 3060090000080, NULL, 1, 1, -1, 1, 0, 'Trưởng Thương Hội Tinh Linh', -1, -1, 0, 'Muốn thưởng thức đặc sản Tinh Linh Thành không?', 7, 10, 2567, 703, NULL, -1, 2060090000080, -1, NULL, 0, NULL, '-1', -1, 1, 1),
	(216, NULL, 0, 0, 0, -1, NULL, 3060100000037, NULL, 1, 1, -2, -1, 0, 'Thủ Lĩnh Cường Đạo', -1, -1, 30, '(Cần 3 người lập nhóm, các thành viên trong nhóm đạt cấp 50 trở lên)', 7, 100, 1437, 1142, NULL, -1, 2060090100037, -1, 'if( c )\r{\r\tvar script_line = Number(LINE_SERVER_ID)+1; \r\tvar script_map = getRandMap([9,10,26,27,31,33,34,41]); //东玄城，精灵城，曙光平原，沉默森林，仙朵拉城，朵拉雪地，鹦舞仙境，禁忌平原\r\tvar nameStr = encode(TBL_CHARACTOR,c.data.id,c.data.name); \r\tvar script_rand = rand3(1,2);\r\tif(script_rand == 1)\r\t{\r\t\taddMultiNpcIns(235,script_map,5,30);\r\t\tsystemMidMsgBroadcast(Msg.replace(Lang.NPC_ScriptOff6, { "leader" : nameStr , "line" : script_line , "place" : getMapNameByIndex(script_map) } )); \r\t}\r}', 0, NULL, 'all', -1, 19, 1),
	(219, NULL, 0, 0, 112, -1, NULL, 3060100001057, NULL, 1, 1, -1, 1, 0, 'Phù Chú Vương', -1, -1, 0, 'Ta nguyền rủa ngươi, sợ chưa?', 0, 23, 2649, 842, NULL, -1, 2060090100057, -1, NULL, NULL, NULL, '3226', 1, 10, 1),
	(231, NULL, NULL, 0, 0, -1, NULL, 3060090000014, NULL, 1, 1, -1, 1, 0, 'Trưởng Thôn Stoff', -1, -1, 0, 'Xuất Vân Thôn được xây dựng trên đỉnh núi. Năm xưa khi tổ tiên chúng ta đến đại lục Vô Ưu đã bám trụ lại đây, cuối cùng trở thành chủ nhân của đại lục, vì vậy chúng ta coi đây là khởi điểm của mọi sự.', 0, 1, 389, 893, NULL, -1, 2060090000014, -1, NULL, NULL, NULL, '-1', -1, 1, 1),
	(233, NULL, NULL, 0, 0, -1, NULL, 3060090000067, NULL, 1, 1, -1, 1, 0, 'Tiệm Thuốc Ông Vương', -1, -1, 0, 'Kim Linh Tử của rừng Huyền Lâm có thể chữa bại liệt, cỏ Vân Vụ của Trầm Thụy Lâm có thể chữa đau bụng, những thứ thuốc mới này đều phải ghi chép lại mới được… À, quý khách trông xanh xao quá, cần mua thuốc gì nào?', 7, 1, 1610, 1040, NULL, -1, 2060090000067, -1, NULL, 2, NULL, '-1', -1, 2, 1),
	(238, NULL, NULL, 0, 0, -1, NULL, 3060090000068, NULL, 1, 1, -1, 1, 0, 'Tiệm Trang Bị Isla', -1, -1, 0, 'Phải có trang bị tốt trên người thì mới có thể chiến đấu thật tốt! Nhớ bảo quản kỹ trang bị của mình, khi không còn độ bền thì nhớ phải sửa chữa.', 0, 1, 630, 486, NULL, -1, 2060090000068, -1, NULL, 1, NULL, '-1', -1, 2, 1),
	(243, 'new|2024/1/1/0/0/0-2024/1/9/23/59/0', 0, 0, 0, -1, NULL, 3060090000001, NULL, 1, 1, -1, 1, 0, 'Sứ Giả Năm Mới', -1, -1, 0, 'Năm mới vui vẻ, phát tài! Bạn có thể tự tạo cho mình những tấm thiệp độc đáo dành tặng cho bạn bè.', 7, 9, 3029, 1186, NULL, -1, 2060090000001, -1, NULL, 72, NULL, '-1', -1, 1, 1),
	(245, '0-23|0-6|31-31|1-1', 0, 0, 0, -1, NULL, 3060090000001, NULL, 1, 1, -1, 1, 0, 'Sứ Giả Sự Kiện Tết Nguyên Tiêu', -1, -1, 0, 'Điểm thưởng sự kiện đạt mức nhất định thì có thể đến chỗ ta để đổi lấy một số vật phẩm O(∩_∩)O', 7, 9, 3031, 1223, NULL, -1, 2060090000001, -1, NULL, 14, NULL, '-1', -1, 1, 1),
	(246, '0-23|0-6|31-31|1-1', 0, 0, 0, -1, NULL, 3060100100003, NULL, 1, 1, -1, 1, 0, 'Sứ Giả Lễ Tình Nhân', -1, -1, 0, 'Nhiệm vụ này có 10 vòng, nếu bỏ cuộc giữa chừng thì cần chờ 10 phút sau mới có thể nhận lại O(∩_∩)O', 7, 9, 3159, 1152, NULL, -1, 2060100100003, -1, NULL, 11, NULL, '-1', -1, 1, 1),
	(247, NULL, NULL, 0, 0, -1, NULL, 3060090000013, NULL, 1, 1, -1, 1, 0, 'Thủ Kho', -1, -1, 0, 'Nếu như đồ đạc quá nhiều, ngươi có thể gửi một ít lại chỗ ta, bảo đảm tuyệt đối an toàn.', 7, 1, 1212, 243, NULL, -1, 2060090000013, -1, NULL, NULL, NULL, '-1', -1, 7, 1),
	(376, NULL, 0, 0, 0, -1, NULL, 3060090000022, NULL, 1, 1, -1, 1, 0, 'Nhà Hàng Âu Dương', -1, -1, 0, 'Ở đây ta có những món ăn thơm ngon nhất thành Đông Thành.', 0, 9, 3137, 2566, NULL, -1, 2060090000022, -1, NULL, 21, NULL, '-1', -1, 2, 1),
	(248, '12-23|0-6|31-31|1-1', 0, 0, 0, -1, NULL, 3060100001100, NULL, 1, 1, -1, 1, 0, 'Trưởng Lão Hồng Bao', -1, -1, 0, 'Trong khoảng thời gian từ 14 đến 16 tháng 2 năm 2010, người chơi cấp 30 trở lên mỗi ngày có thể đến chỗ ta để nhận bao lì xì, trong đó có thể mở ra lượng kim phiếu nhất định, Pháo Hoa Ngũ Sắc, Pháo Trúc, người chơi may mắn còn có thể nhận được bảo thạch O', 7, 900, 2442, 608, NULL, -1, 2060090100100, -1, NULL, NULL, NULL, '-1', -1, 1, 1),
	(249, NULL, 0, 0, 0, -1, NULL, 3060100001100, NULL, 1, 1, -1, 1, 0, 'Đại Sứ Lao Động', -1, -1, 0, 'Nhiệm vụ này gồm 10 vòng, bỏ cuộc giữa chừng hoặc hoàn thành đủ 10 vòng thì cần phải chờ 10 phút sau mới có thể nhận lại O(∩_∩)O', 7, 900, 3029, 1186, NULL, -1, 2060090100100, -1, NULL, NULL, NULL, '-1', -1, 1, 1),
	(250, '0-23|0-6|1-31|0-11|guijie', 0, 0, 0, -1, NULL, 3060100001100, NULL, 1, 1, -1, 1, 0, 'Sứ Giả Sự Kiện Vong Hồn', 1, 1, 0, 'Vào các đêm cúng vong hồn, rất nhiều Tiểu Quỷ ham chơi đã chạy đến Vô Ưu Đại Lục, hù dọa mọi người, quấy rầy cuộc sống bình yên của dân lành. Sứ Giả Sự Kiện Vong Hồn hi vọng mọi người có thể bắt được bọn chúng, trả lại sự bình yên cho thôn làng', 7, 900, 3029, 1186, NULL, -1, 2060090100100, -1, NULL, 0, NULL, '-1', -1, 1, 1),
	(251, '0-23|0-6|31-31|1-1', 0, 0, 0, -1, NULL, 3060090000113, NULL, 1, 1, -1, 1, 0, 'Cây Giáng Sinh', -1, -1, -1, NULL, 0, 31, 3784, 2312, NULL, -1, 2060090000113, -1, NULL, NULL, NULL, '-1', -1, 1, 1),
	(262, '0-23|0-6|30-30|1-1', 0, 0, 0, -1, NULL, 3060090000001, NULL, 1, 1, -1, 1, 0, 'Thợ Trồng Hoa', -1, -1, 0, 'Chúc mừng năm mới, mặc dù tên ta là Thợ Trồng Hoa nhưng thật sự ta không biết trồng mà chỉ biết trang trí hoa thôi', 7, 34, 810, 810, NULL, -1, 2060090000001, -1, NULL, NULL, NULL, '-1', -1, 1, 1),
	(274, NULL, NULL, 0, 0, -1, NULL, 3060090000002, NULL, 1, 1, -1, 1, 0, 'Tiệm Vũ Khí Mark', -1, -1, 0, 'Chào quý khách! Có phải Ali ở quán rượu đó không? Rượu mật ong ta đặt mua đâu? Hả? Nhận nhầm người rồi à? Xin lỗi nhé! Ta xin tự giới thiệu, ta tên là Mark, \"thợ rèn ma men\" chính là đại thúc ta, có việc gì cần cứ đến tìm ta nhé. Ngươi cũng không cần phải', 0, 9, 3260, 1603, NULL, -1, 2060090000002, -1, NULL, 25, NULL, '-1', -1, 2, 1),
	(275, NULL, NULL, 0, 0, -1, NULL, 3060090000078, NULL, 1, 1, -1, 1, 0, 'Tiệm Tạp Hóa Ông Mộ', -1, -1, 0, 'Đây là tiệm tạp hóa Đông Huyền, vật phẩm ở đây tuy đơn giản nhưng trong thời khắc quan trọng sẽ phát huy hiệu quả đến không ngờ, nên cho dù như thế nào, hãy cố gắng mua một ít mang theo trên người vẫn tốt hơn.', 0, 9, 2088, 2059, NULL, -1, 2060090000078, -1, NULL, 32, NULL, '-1', -1, 2, 1),
	(283, NULL, NULL, 0, 0, -1, NULL, 3060090000080, NULL, 1, 1, -1, 1, 0, 'Quản Lý Đấu Giá', -1, -1, 0, 'Hello, xin hoan nghênh các ngươi đến chợ bán đấu giá của Đông Huyền, ở đây ngươi có thể treo những vật phẩm mà ngươi không dùng lên, đợi những người chơi khác cần chúng sẽ chọn mua. Không cần lo lắng tìm người mua ở khắp nơi, cũng không cần lo lắng chuyện', 7, 9, 3513, 1264, NULL, -1, 2060090000080, -1, NULL, 0, NULL, '-1', -1, 5, 1),
	(288, NULL, NULL, 0, 18, -1, NULL, 3060090000014, NULL, 1, 1, -1, 1, 0, 'Thủ Thư', -1, -1, 0, 'Sách là nấc thang tiến bộ, là kiến thức được đúc kết lại! Khi chiến đấu mệt rồi, thì nên ghé lại đây xem sách, có khi ngươi sẽ tìm được những thông tin hữu ích đấy.', 0, 9, 704, 784, NULL, -1, 2060090000014, -1, NULL, 0, NULL, '-1', -1, 1, 1),
	(429, NULL, NULL, 0, -70, -1, '|9,Đông Huyền Thành,10,2228,1336|30,Quyến Cố Thành,100,1153,1163|', 3060090000070, NULL, 1, 1, -1, 1, 0, 'Tinh Linh Dịch Chuyển Huyền Lâm', -1, -1, 0, 'Ngươi muốn về Đông Huyền Thành ư?', 0, 39, 184, 1006, NULL, -1, 2060090000070, -1, NULL, NULL, NULL, '-1', -1, 9, 1),
	(290, NULL, NULL, 0, 0, -1, NULL, 3060090000079, NULL, 1, 1, -1, 1, 0, 'Thành Chủ Tinh Linh', -1, -1, 0, 'Xin chào, hoan nghênh đến với Tinh Linh Thành nằm ở phía bắc Trầm Thụy Lâm. Không phải ta ba hoa, nhưng thực sự thành Tinh Linh là thành phố màu xanh trong sạch nhất trên đại lục, ngay cả thành Tiên Lạp của đảo Băng cũng không sánh kịp.', 7, 10, 2281, 436, NULL, -1, 2060090000079, -1, NULL, NULL, NULL, '-1', -1, 1, 1),
	(299, NULL, NULL, 0, 0, -1, '|12,Bàn Địa Tộc,10,800,1285|13,Liêu Vân Tộc,10,1800,1256|11,Linh Vũ Tộc,10,465,1214|32,Thiên Khung Tộc,10,1193,1341|39,Huyền Lâm Tộc,10,210,1180|25,Lưu Hỏa Tộc,10,2033,1500|', 3060090000011, NULL, 1, 1, -1, 1, 0, 'Hướng Dẫn Viên Ryan', -1, -1, 0, 'Chiến Binh  →→→→→→ Bàn Địa Tộc Nhạc Công →→→→→→ Liêu Vân Tộc Danh Y     →→→→→→ Linh Vũ Tộc Xạ Thủ     →→→→→→ Thiên Khung Tộc Thợ Săn   →→→→→→ Huyền Lâm Tộc Hiệp Sĩ      →→→→→→ Lưu Hỏa Tộc', 7, 9, 2218, 1538, NULL, -1, 2060090000011, -1, NULL, NULL, NULL, '-1', -1, 9, 1),
	(310, NULL, 0, 1, 0, -1, NULL, 3060090000008, NULL, 1, 1, -1, 1, 0, 'Đạo Sư Bàn Địa', -1, -1, 0, 'Đây là Bàn Địa Tộc phía đông Quang Bình Nguyên. Là một tộc cổ có hàng trăm năm lịch sử, chúng ta nổi tiếng khắp đại lục về kiến thức kiến trúc thổ mộc và thăm dò địa chất. Hôm nay cùng với sáu tộc lớn khác xây dựng nên Đông Huyền, vị trí của chúng ta nằm', 0, 12, 331, 451, NULL, -1, 2060090000024, -1, NULL, 0, NULL, '3-0', 1, 11, 1),
	(311, NULL, NULL, 3, 0, -1, NULL, 3060090000011, NULL, 1, 1, -1, 1, 0, 'Đạo Sư Linh Vũ', -1, -1, 0, 'Hoan nghênh đến với Linh Vũ Tộc. Linh Vũ Tộc là một tộc cổ, cùng với năm tộc nổi tiếng khác. Gia tộc luôn bồi dưỡng về lễ nghĩa, dược liệu và truyền dạy những kỹ năng trị liệu và phụ trợ và được nhiều người tôn trọng. Từ trước đến nay chúng ta luôn trong', 7, 11, 1469, 543, NULL, -1, 2060090000011, -1, NULL, NULL, NULL, '3-0', -1, 11, 1),
	(330, NULL, 0, 0, 0, -1, NULL, 3050080000001, NULL, 1, 1, -1, 1, 0, 'Kho Sách Bàn Địa', -1, -1, -1, 'Nơi đây có bán sách kỹ năng.', 7, 12, 1823, 1140, NULL, -1, 2060090300001, -1, NULL, 34, NULL, '-1', -1, 2, 1),
	(333, NULL, NULL, 0, -40, -1, '|9,Đông Huyền Thành,10, 1550,1207|30,Quyến Cố Thành,100,1153,1163|', 3060090000070, NULL, 1, 1, -1, 1, 0, 'Tinh Linh Dịch Chuyển Linh Vũ', -1, -1, 0, 'Ngươi muốn về Đông Huyền Thành ư?', 7, 11, 272, 1260, NULL, -1, 2060090000070, -1, NULL, NULL, NULL, '-1', -1, 9, 1),
	(339, NULL, 0, 0, 0, -1, NULL, 3050070000001, NULL, 1, 1, -1, 1, 0, 'Tộc Trưởng Bàn Địa', -1, -1, -1, 'Ha ha, hoan nghênh các ngươi gia nhập Bàn Địa Tộc, ta là bậc tiền bối của các ngươi, về sau ta sẽ phụ trách phần kỹ năng, nếu có vấn đề gì không hiểu, hãy đến hỏi, ta sẽ cố gắng giải đáp.', 0, 12, 1514, 745, NULL, -1, 2060090200029, -1, NULL, NULL, NULL, '-1', -1, 6, 1),
	(342, NULL, 0, 0, 0, -1, NULL, 3050080000002, NULL, 1, 1, -1, 1, 0, 'Tộc Trưởng Linh Vũ', -1, -1, -1, 'Ta là Tộc Trưởng Linh Vũ, muốn học kỹ năng gia tộc thì cứ đến tìm ta.', 0, 11, 446, 849, NULL, -1, 2060090200030, -1, NULL, NULL, NULL, '-1', -1, 6, 1),
	(373, NULL, NULL, 0, 0, -1, NULL, 3060090000003, NULL, 1, 1, -1, 1, 0, 'Tiệm Trang Bị Mary', -1, -1, 0, 'Hoan nghênh đến Đông Huyền Thành. Chỗ ta chuyên bán quần áo.', 0, 9, 1607, 2287, NULL, -1, 2060090000003, -1, NULL, 23, NULL, '-1', -1, 2, 1),
	(377, NULL, NULL, 0, 0, -1, NULL, 3060090000018, NULL, 1, 1, -1, 1, 0, 'Nghiên Cứu Gia XX', -1, -1, 0, 'Ta là nghiên cứu gia XX, ngươi thấy hai chữ XX kỳ lạ ư? Có lúc ta cũng cảm thấy như vậy, nhưng ngươi không thấy gọi thế nghe rất ngầu sao? XX là vũ trụ, là vạn vật trên thế gian. Khi ngươi cảm nhận được ý nghĩa thật sự của từ XX thì có thể cùng ta nghiên', 0, 9, 2232, 890, NULL, -1, 2060090000018, -1, NULL, 0, NULL, '-1', -1, 1, 1),
